const r = await tools.update_plan({plan:[
  {step:"Resolve the exact uncommitted review scope and approved artifact contract",status:"in_progress"},
  {step:"Run independent correctness, migration/resilience, and test/requirements review lanes",status:"pending"},
  {step:"Trace and validate every surviving finding against concrete code paths",status:"pending"},
  {step:"Return severity-ordered findings or CLEAN under the requested contract",status:"pending"}
]});
text(r);

const r = await tools.update_plan({explanation:"Read-only review complete. Independent validation confirmed the merge-resolution omission, unterminated NUL framing, and missing-repository warning defects; it rejected the proposed ancestry-exit and total-latency defects as non-actionable under the approved contract.","plan":[
  {step:"Resolve the exact uncommitted review scope and approved artifact contract",status:"completed"},
  {step:"Run independent correctness, migration/resilience, and test/requirements review lanes",status:"completed"},
  {step:"Trace and validate every surviving finding against concrete code paths",status:"completed"},
  {step:"Return severity-ordered findings or CLEAN under the requested contract",status:"completed"}
]});
text(r);
